// FormData is the global form fill data instance
var FormData FormFillData

func init() {
	FormData = DefaultFormFillData
}

// FormFillData contains suggestions for form filling
type FormFillData struct {
	Email       string `yaml:"email"`
	Color       string `yaml:"color"`
	Password    string `yaml:"password"`
	PhoneNumber string `yaml:"phone"`
	Placeholder string `yaml:"placeholder"`
}

var DefaultFormFillData = FormFillData{
	Email:       fmt.Sprintf("%s@example.org", xid.New().String()),
	Color:       "#e66465",
	Password:    "katanaP@assw0rd1",
	PhoneNumber: "2124567890",
	Placeholder: "katana",
}

var formDSLEngine *dsl.Engine
var formDSLOnce sync.Once

func getFormDSLEngine() *dsl.Engine {
	formDSLOnce.Do(func() {
		engine, err := dsl.NewEngine()
		if err != nil {
			return
		}
		for name, fn := range dsl.FakerFunctions() {
			engine.HelperFunctions[name] = fn
		}
		formDSLEngine = engine
	})
	return formDSLEngine
}

// resolveField evaluates a string through the DSL engine if it
// looks like a function call (contains parentheses). Plain values
// like "test@example.com" or "5551234567" are returned as-is.
func resolveField(value string) string {
	if value == "" || !strings.Contains(value, "(") {
		return value
	}
	engine := getFormDSLEngine()
	if engine == nil {
		return value
	}
	result, err := safeEvalExpr(engine, value)
	if err != nil {
		return value
	}
	return fmt.Sprintf("%v", result)
}

// safeEvalExpr wraps engine.EvalExpr with panic recovery since the
// underlying govaluate library can panic on inputs that aren't
// valid expressions (e.g. plain strings treated as undefined variables).
func safeEvalExpr(engine *dsl.Engine, expr string) (result interface{}, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("expression eval panic: %v", r)
		}
	}()
	return engine.EvalExpr(expr, map[string]interface{}{})
}

// Resolve evaluates all fields through the DSL engine, resolving any
// helper function calls like rand_email() or rand_password(8, true).
// Plain string values pass through unchanged.
func (f *FormFillData) Resolve() {
	f.Email = resolveField(f.Email)
	f.Color = resolveField(f.Color)
	f.Password = resolveField(f.Password)
	f.PhoneNumber = resolveField(f.PhoneNumber)
	f.Placeholder = resolveField(f.Placeholder)
}

// FormInput is an input for a form field
type FormInput struct {
	Type       string
	Name       string
	Value      string
	Attributes mapsutil.OrderedMap[string, string]
}

// SelectOption is an option for a select input
type SelectOption struct {
	Value      string
	Selected   string
	Attributes mapsutil.OrderedMap[string, string]
}

// FormSelect is a select input for a form field
type FormSelect struct {
	Name          string
	Attributes    mapsutil.OrderedMap[string, string]
	SelectOptions []SelectOption
}

type FormTextArea struct {
	Name       string
	Attributes mapsutil.OrderedMap[string, string]
}

// FormInputFillSuggestions returns a list of form filling suggestions
// for inputs returning the specified recommended values.
func FormInputFillSuggestions(inputs []FormInput) mapsutil.OrderedMap[string, string] {
	return FormInputFillSuggestionsWithDecider(context.Background(), nil, inputs)
}

// FormInputFillSuggestionsWithDecider is FormInputFillSuggestions that asks d
// about text fields the built-in rules cannot classify. d may be nil.
func FormInputFillSuggestionsWithDecider(ctx context.Context, d decider.Decider, inputs []FormInput) mapsutil.OrderedMap[string, string] {
	data := mapsutil.NewOrderedMap[string, string]()

	// Fill checkboxes and radioboxes first or default values first
	for _, input := range inputs {
		switch input.Type {
		case "radio":
			// Use a single radio name per value
			if !data.Has(input.Name) {
				data.Set(input.Name, input.Value)
			}
		case "checkbox":
			data.Set(input.Name, input.Value)

		default:
			// A real value wins. Placeholder text is only a fallback after
			// semantic filling, so it must not hide the field from that pass.
			if input.Value != "" {
				data.Set(input.Name, input.Value)
			}
		}
	}

	// getIntWithdefault returns the integer value of the key or default value
	getIntWithdefault := func(input *FormInput, key string, defaultValue int) int {
		if value, ok := input.Attributes.Get(key); ok {
			if intValue, err := strconv.Atoi(value); err == nil {
				return intValue
			}
		}
		return defaultValue
	}

	// Fill rest of the inputs based on their types or name and ids
	for _, input := range inputs {
		if input.Value != "" {
			continue
		}
		switch input.Type {
		case "color":
			data.Set(input.Name, FormData.Color)
		case "number", "range":
			min := getIntWithdefault(&input, "min", 1)
			max := getIntWithdefault(&input, "max", 10)
			step := getIntWithdefault(&input, "step", 1)
			val := min + step
			if val > max {
				val = max - step
			}
			data.Set(input.Name, strconv.Itoa(val))
		default:
			value := semanticValue(ctx, d, input)
			if value == "" {
				if placeholder, ok := input.Attributes.Get("placeholder"); ok {
					value = placeholder
				} else {
					value = FormData.Placeholder
				}
			}
			data.Set(input.Name, value)
		}
	}
	return data
}

// FormSelectFill fills a map with selected values from a slice of FormSelect structs.
// It iterates over each FormSelect struct in the inputs slice and checks for a selected option.
// If a selected option is found, it adds the corresponding value to the map using the input's name as the key.
// If no option is selected, it selects the first option and adds its value to the map.
// The function returns the filled map.
func FormSelectFill(inputs []FormSelect) mapsutil.OrderedMap[string, string] {
	data := mapsutil.NewOrderedMap[string, string]()
	for _, input := range inputs {
		for _, option := range input.SelectOptions {
			if option.Selected != "" {
				data.Set(input.Name, option.Value)
				break
			}
		}

		// If no option is selected, select the first one
		if !data.Has(input.Name) && len(input.SelectOptions) > 0 {
			data.Set(input.Name, input.SelectOptions[0].Value)
		}
	}
	return data
}

