func semanticValue(ctx context.Context, d decider.Decider, input FormInput) string {
	value := typedValue(fieldSemantic(ctx, d, input))
	if pattern, ok := input.Attributes.Get("pattern"); ok {
		value = matchPattern(pattern, value)
