// bodyFormTagParser parses forms from response, asking d about fields the rules cannot fill
func bodyFormTagParser(d decider.Decider) ResponseParserFunc {
	return func(resp *navigation.Response) []*navigation.Request {
		return parseForms(deciderContext(resp), resp, d)
	}
}

// deciderContext is the crawl context carried by the response request.
// Standard and hybrid attach it so cancelling the crawl stops a decision.
func deciderContext(resp *navigation.Response) context.Context {
	if resp != nil && resp.Resp != nil && resp.Resp.Request != nil {
		if ctx := resp.Resp.Request.Context(); ctx != nil {
			return ctx
		}
	}
	return context.Background()
}

func parseForms(ctx context.Context, resp *navigation.Response, d decider.Decider) (navigationRequests []*navigation.Request) {
	resp.Reader.Find("form").Each(func(i int, item *goquery.Selection) {
		href, _ := item.Attr("action")
		encType, ok := item.Attr("enctype")
		if !ok || encType == "" {
			encType = "application/x-www-form-urlencoded"
		}

		method, _ := item.Attr("method")
		if method == "" {
			method = "GET"
		}
		method = strings.ToUpper(method)

		actionURL := resp.AbsoluteURL(href)
		if actionURL == "" {
			return
		}

		parsed, err := urlutil.Parse(actionURL)
		if err != nil {
			gologger.Warning().Msgf("bodyFormTagParser :failed to parse url %v got %v", actionURL, err)
			return
		}

		isMultipartForm := strings.HasPrefix(encType, "multipart/")

		queryValuesWriter := urlutil.NewOrderedParams()
		queryValuesWriter.IncludeEquals = true
		var sb strings.Builder
		var multipartWriter *multipart.Writer

		if isMultipartForm {
			multipartWriter = multipart.NewWriter(&sb)
		}

		// Get the form field suggestions for all elements in the form
		formFields := []interface{}{}
		item.Find("input, select, textarea").Each(func(index int, item *goquery.Selection) {
			if len(item.Nodes) == 0 {
				return
			}
			formFields = append(formFields, utils.ConvertGoquerySelectionToFormField(item))
		})

		dataMap := utils.FormFillSuggestionsWithDecider(ctx, d, formFields)
		dataMap.Iterate(func(key, value string) bool {
			if key == "" {
				return true
			}
			if isMultipartForm {
				_ = multipartWriter.WriteField(key, value)
			} else {
				queryValuesWriter.Set(key, value)
			}
			return true
		})

		// Guess content-type
		var contentType string
		if multipartWriter != nil {
			_ = multipartWriter.Close()
			contentType = multipartWriter.FormDataContentType()
		} else {
			contentType = encType
		}

		req := &navigation.Request{
			Method:       method,
			URL:          actionURL,
			Depth:        resp.Depth,
			RootHostname: resp.RootHostname,
			Tag:          "form",
			Attribute:    "action",
			Source:       resp.Resp.Request.URL.String(),
		}
		switch method {
		case "GET":
			parsed.Params.Merge(queryValuesWriter.Encode())
			req.URL = parsed.String()
		case "POST":
			if multipartWriter != nil {
				req.Body = sb.String()
			} else {
				req.Body = queryValuesWriter.Encode()
			}
			req.Headers = make(map[string]string)
			req.Headers["Content-Type"] = contentType
		}
		navigationRequests = append(navigationRequests, req)
	})
	return

