	popup.extraHeaders = extra
	if err := popup.handlePageDialogBoxes(); err != nil {
		return nil, err
	}
	if _, err := page.EvalOnNewDocument(stealth.JS); err != nil {
		return nil, err
	}
	if err := js.InitJavascriptEnvWithHooks(page, l.opts.Interactive); err != nil {
		return nil, err
	}
	return popup, nil
}

// backoffCountSleeper returns a sleeper that uses backoff strategy but stops after max attempts.
// It combines the functionality of BackoffSleeper and CountSleeper.
func backoffCountSleeper(initInterval, maxInterval time.Duration, maxAttempts int, algorithm func(time.Duration) time.Duration) rodutils.Sleeper {
	backoff := rodutils.BackoffSleeper(initInterval, maxInterval, algorithm)
	count := rodutils.CountSleeper(maxAttempts)

	return rodutils.EachSleepers(backoff, count)
}

func (b *BrowserPage) handlePageDialogBoxes() error {
	sessionPage := b.CurrentPage()
	patterns := []*proto.FetchRequestPattern{{
		URLPattern:   "*",
		RequestStage: proto.FetchRequestStageResponse,
	}}
	// Pausing at the request stage costs a CDP round trip per request, so only
	// do it when there are custom headers to attach.
	if len(b.extraHeaders) > 0 {
		patterns = append(patterns, &proto.FetchRequestPattern{
			URLPattern:   "*",
			RequestStage: proto.FetchRequestStageRequest,
		})
	}
	err := proto.FetchEnable{Patterns: patterns}.Call(sessionPage)
	if err != nil {
		return errors.Wrap(err, "could not enable fetch domain")
	}

	go sessionPage.EachEvent(
		func(e *proto.PageJavascriptDialogOpening) {
			_ = proto.PageHandleJavaScriptDialog{
				Accept:     true,
				PromptText: xid.New().String(),
			}.Call(b.CurrentPage())

